# Verify every cited ID exists and embed first definition excerpt for review.
srs=(ROOT/'SRS_v1.md').read_text(encoding='utf-8')
for item in CASES:
 for ref in item['refs']:
  assert re.search(r'(?<![A-Z0-9-])'+re.escape(ref)+r'(?![0-9.])',srs),ref
assert len({i['id'] for i in CASES})==len(CASES)
for i in CASES:
 assert all(i[k] for k in ['title','role','pre','data','steps','expected','basis'])
(ROOT/'works/test-src/cases.json').write_text(json.dumps(CASES,ensure_ascii=False,indent=2),encoding='utf-8')
print(f'{len(CASES)} cases; all references exist; 98 role-menu cases')
